local R=dofile('tests/kernel_farms_harness.lua')
local n=0
local function case(name,fn)R.clientCase(name,fn);n=n+1 end
case('start zones',function(r)r.apply(R.seed());assert(#r.farms.zones==1 and #r.farms.routeZones==0)end)
case('nil snapshot empty',function(r)r.apply(nil);assert(#r.farms.zones==0)end)
case('disabled snapshot',function(r)local p=R.seed();p.settings.enabled=false;r.apply(p);assert(#r.farms.zones==0)end)
case('disabled farm hidden',function(r)local p=R.seed();p.farms[1].enabled=false;r.apply(p);assert(#r.farms.zones==0)end)
for _,kind in ipairs({'job','gang'})do for _,grade in ipairs({0,1,2,3})do case('primary access '..kind..grade,function(r)
 local p=R.seed();p.farms[1].public=false;p.farms[1].groupType=kind;p.farms[1].groupName=kind=='job'and'police'or'ballas';p.farms[1].minGrade=grade;r.apply(p)
 assert(#r.farms.zones==(grade<=(kind=='job'and 2 or 1)and 1 or 0))
end)end end
case('secondary job not used',function(r)local p=R.seed();p.farms[1].public=false;p.farms[1].groupName='farmer';r.playerData.jobs={farmer=5};r.apply(p);assert(#r.farms.zones==0)end)
case('vector conversion fallback',function(r)r.vectorError=true;r.apply(R.seed());assert(#r.farms.zones==1)end)
case('no target provider',function(r)r.library.target=nil;r.apply(R.seed());assert(#r.farms.zones==0)end)
case('start route points/blip',function(r)r.start();assert(r.farms.active.pointIndex==1 and #r.farms.routeZones==2 and #r.farms.blips==1)end)
case('start no points',function(r)local p=R.seed();p.farms[1].items[1].points={};r.apply(p);r.targets[r.farms.zones[1]].options[1].onSelect();r.last.options[1].onSelect();assert(not r.farms.active)end)
case('start refusal',function(r)r.rpcHook=function()return false,'daily_limit'end;r.start();assert(not r.farms.active)end)
case('start exception',function(r)r.rpcHook=function()error('fixture-rpc',0)end;assert(not pcall(r.start))end)
case('already active route',function(r)r.start();local active=r.farms.active;r.last.options[1].onSelect();assert(r.farms.active==active)end)
case('wrong point rejected',function(r)r.start();r.collect(2);assert(r.farms.active.collected==0 and not r.farms.busy)end)
case('canInteract current point/busy',function(r)
 r.start();assert(r.targets[r.farms.routeZones[1]].options[1].canInteract());assert(not r.targets[r.farms.routeZones[2]].options[1].canInteract())
 r.farms.busy=true;assert(not r.targets[r.farms.routeZones[1]].options[1].canInteract())
end)
case('in vehicle refuses',function(r)r.start();r.inVehicle=true;r.collect();assert(not r.farms.busy and #r.dynamicThreads==0)end)
for _,vehicle in ipairs({0,99})do case('required vehicle missing '..vehicle,function(r)
 r.start();r.farms.active.item.required.vehicle='adder';r.lastVehicle=vehicle;r.vehicleModel='hash:other';r.collect();assert(#r.dynamicThreads==0)
end)end
case('required previous vehicle accepted',function(r)r.start();r.farms.active.item.required.vehicle='adder';r.lastVehicle=99;r.vehicleModel='hash:adder';r.collect();assert(r.farms.active.collected==1)end)
case('collect advances and finishes',function(r)r.start();r.collect(1);assert(r.farms.active.pointIndex==2);r.collect(2);assert(not r.farms.active and #r.farms.routeZones==0 and #r.farms.blips==0)end)
case('unlimited loops',function(r)r.start();r.farms.active.item.unlimited=true;r.collect(1);r.collect(2);assert(r.farms.active.pointIndex==1)end)
case('random uses sampled point',function(r)r.randomHigh=true;local p=R.seed();p.farms[1].items[1].randomRoute=true;r.apply(p);r.targets[r.farms.zones[1]].options[1].onSelect();r.last.options[1].onSelect();assert(r.farms.active.pointIndex==2);r.collect(2);assert(r.farms.active.pointIndex==2)end)
case('max per route local finish',function(r)r.start();r.farms.active.item.limits={enabled=true,maxPerRoute=1};r.collect();assert(not r.farms.active and #r.farms.routeZones==0)end)
case('progress cancel',function(r)r.start();r.progressResult=false;r.collect();assert(not r.farms.busy and r.farms.active.collected==0)end)
case('progress numeric one not true',function(r)r.start();r.progressResult=1;r.collect();assert(r.farms.active.collected==0)end)
case('progress exception inherited busy',function(r)r.start();r.progressError=true;assert(not pcall(r.collect)and r.farms.busy)end)
case('collect refusal after progress',function(r)r.start();r.rpcHook=function()return false,'required_item_missing'end;r.collect();assert(not r.farms.busy and r.farms.active.collected==0)end)
case('collect RPC exception inherited busy',function(r)r.start();r.rpcHook=function()error('fixture-rpc',0)end;assert(not pcall(r.collect)and r.farms.busy)end)
case('malformed collect response fallback',function(r)r.start();r.rpcHook=function()return true,false end;r.collect();assert(r.farms.active.collected==1)end)
for _,preset in ipairs({'pickup','garden','weld','hammer','clipboard','mechanic','construction','electrician','janitor','maid','binoculars','drilling','mechanic2','unknown'})do
 case('animation '..preset,function(r)
  r.start();r.farms.active.item.animation={mode='preset',preset=preset}
  r.progressHook=function()local co=coroutine.create(r.dynamicThreads[1]);local ok,delay=coroutine.resume(co);assert(ok and delay==750);r.animation=co;return true end
  r.collect();assert(coroutine.resume(r.animation));assert(coroutine.status(r.animation)=='dead')
 end)
end
case('manual animation',function(r)r.start();r.farms.active.item.animation={mode='manual',dict='custom',anim='loop'};r.collect()end)
case('scenario animation',function(r)r.start();r.farms.active.item.animation={mode='scenario',scenario='WORLD_HUMAN_WELDING'};r.collect()end)
case('animation dict timeout continues progress',function(r)
 r.start();r.animLoaded=false;local co=r.run(function()r.collect()end)
 for _=1,8 do if coroutine.status(co)=='dead'then break end;r.resume(co)end
 assert(coroutine.status(co)=='dead'and r.farms.active.collected==1)
end)
case('stop menu finishes route',function(r)r.start();r.targets[r.farms.zones[1]].options[1].onSelect();r.last.options[2].onSelect();assert(not r.farms.active and #r.farms.routeZones==0)end)
case('snapshot refresh stops route',function(r)r.start();r.apply(R.seed());assert(not r.farms.active and #r.farms.routeZones==0 and #r.farms.zones==1)end)
for _,event in ipairs({'QBCore:Client:OnJobUpdate','QBCore:Client:OnGangUpdate'})do case(event,function(r)r.start();r.fireFarm(event);assert(not r.farms.active)end)end
case('hydration worker',function(r)r.value=R.seed();local co,delay=r.run(r.initial[1]);assert(delay==2000);r.resume(co);assert(#r.farms.zones==1)end)
case('own stop leaves route targets inherited',function(r)r.start();r.fireFarm('onResourceStop','forge-core');assert(#r.farms.zones==0 and #r.farms.blips==0 and #r.farms.routeZones==2 and r.farms.active)end)
case('unrelated stop ignored',function(r)r.start();r.fireFarm('onResourceStop','other');assert(#r.farms.zones==1)end)
case('refresh during pending progress',function(r)
 r.start();r.progressHook=function()return coroutine.yield('progress')end
 local co,delay=r.run(function()r.collect()end);assert(delay=='progress'and r.farms.busy)
 r.apply(R.seed());r.progressHook=nil;local ok,e=coroutine.resume(co,true);assert(ok,e);assert(not r.farms.active and not r.farms.busy)
end)
case('stop during progress can resume inherited',function(r)
 r.start();r.progressHook=function()return coroutine.yield('progress')end
 local co=r.run(function()r.collect()end);r.fireFarm('onResourceStop','forge-core')
 local ok,e=coroutine.resume(co,true);assert(ok,e);assert(r.farms.active.collected==1)
end)
print('PASS farms client/route/progress differentials '..n)
